🤖 [Qwen Edge] Certainly! Below is an example of how to implement a basic singly linked list in C++. This includes the necessary classes and functions to add elements at both ends, retrieve values, check if it's empty, remove elements by value, and print all elements.

```cpp
#include <iostream>

class ListNode {
public:
    int data;
    ListNode* next;

    // Constructor for a new node
    ListNode(int val) : data(val), next(nullptr) {}

    // Destructor to free the memory of the node
    ~ListNode() {
        if (next != nullptr) {
            delete next;
        }
    }
};

class LinkedList {
public:
    ListNode* head = nullptr;

    void appendLeft(int value) {
        ListNode* newNode = new ListNode(value);
        newNode->next = head;
        head = newNode;
    }

    void appendRight(int value) {
        if (head == nullptr) {
            head = new ListNode(value);
        } else {
            ListNode* current = head;
            while (current->next != nullptr) {
                current = current->next;
            }
            ListNode* newNode = new ListNode(value);
            current->next = newNode;
        }
    }

    int get(int index) const {
        if (index < 0 || index >= size()) return -1;

        ListNode* current = head;
        for (int i = 0; i <= index; ++i) {
            current = current->next;
        }
        return current ? current->data : -1;
    }

    bool isEmpty() const {
        return head == nullptr;
    }

    int size() const {
        int count = 0;
        ListNode* current = head;
        while (current != nullptr) {
            ++count;
            current = current->next;
        }
        return count;
    }

    void remove(int value) {
        if (isEmpty()) return;

        if (head->data == value) {
            head = head->next;
            delete head;
            head = nullptr;
            return;
        }

        ListNode* prev = head;
        while (prev->next != nullptr && prev->next->data != value) {
            prev = prev->next;
        }
        if (prev->next == nullptr) return;

        prev->next = prev->next->next;
        delete prev->next;
    }

    void print() const {
        ListNode* current = head;
        while (current != nullptr) {
            std::cout << current->data << " ";
            current = current->next;
        }
        std::cout << std::endl;
    }
};

int main() {
    LinkedList myList;

    myList.appendLeft(1);
    myList.appendRight(2);
    myList.appendRight(3);

    std::cout << "List: ";
    myList.print();  // Output: 1 2 3

    myList.remove(2);
    std::cout << "After removing 2: ";
    myList.print();  // Output: 1 3

    myList.appendLeft(-1);
    std::cout << "Adding -1 at the beginning: ";
    myList.print();  // Output: -1 1 3

    return 0;
}
```

### Explanation:
- **ListNode Class**: This class represents a single node in the linked list. Each node has an `int` data and a pointer to the next node.
- **LinkedList Class**: This class manages the entire linked list, including adding elements at the beginning (`appendLeft`) and end (`appendRight`), retrieving elements by index (`get`), checking if it's empty (`isEmpty`), and removing elements by value (`remove`).
- The `print` method simply traverses the list from the head node to the tail.

This example demonstrates a basic structure for singly linked lists in C++. You can extend this implementation with more features or add methods based on your specific requirements.

