	exampleList = append(exampleList, "a")
	exampleList = append(exampleList, true)

	filtered := filterSlice(exampleList, func(i interface{}) bool {
		return i.(string).Contains("h")
	})

	for _, item := range filtered {
		fmt.Println(item)
	}
}
```

